mapper.select:
SELECT id, department_id, credential_hash, credential_version
FROM public.device
WHERE device_code = #{deviceCode}

mapper.update:
UPDATE public.device
SET last_seen_at = #{seenAt}
WHERE id = #{deviceId}
  AND credential_version = #{credentialVersion}

mapper.select:
SELECT id, department_id, credential_version, status
FROM public.device
WHERE id = #{deviceId}
  AND department_id = #{departmentId}
FOR UPDATE

SELECT id, department_id, credential_version, status
FROM public.device
