  AND department_id = #{departmentId}

mapper.update:
UPDATE public.device
SET credential_tested_version = credential_version,
	credential_tested_at = #{testedAt}
WHERE id = #{deviceId}
  AND status = 'INACTIVE'
  AND credential_version = #{credentialVersion}
